using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
[InitializeOnLoad]public static class Scene05AltarFix{static Scene05AltarFix(){EditorApplication.delayCall+=Run;}static void Run(){if(EditorApplication.isPlaying||File.Exists("Temp/scene05-altar-fix.done"))return;try{var story=UnityEngine.Object.FindObjectOfType<Scene05HomecomingStory>();if(!story)return;story.director.time=0;story.director.Evaluate();story.Sample(0);story.burner.position=new Vector3(0,1,1.4f);PrefabUtility.RecordPrefabInstancePropertyModifications(story.burner);story.father.position=new Vector3(0,.15f,.77f);story.father.rotation=Quaternion.identity;story.touchPoint=new Vector3(0,1.13f,1.285f);story.luggage.position=new Vector3(.42f,.15f,.7f);story.luggage.rotation=Quaternion.Euler(-90,0,0);story.CapturePose();story.exitWaypoints=new[]{new Vector3(.32f,.15f,-.55f),new Vector3(.32f,.15f,-3.98f),new Vector3(1.35f,.15f,-4.02f),story.outside};
var row=UnityEngine.Object.FindObjectsOfType<MeshFilter>(true).First(f=>f.name=="rowhouse_1960");var original=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Project3D/Prefabs/environment/rowhouse_1960.prefab").GetComponentInChildren<MeshFilter>().sharedMesh;File.WriteAllText("Temp/scene05-wall-source.txt","mesh="+original.name+" vertices="+original.vertexCount+" bounds="+original.bounds+" row="+row.transform.position+" rot="+row.transform.eulerAngles+" scale="+row.transform.lossyScale);var mesh=UnityEngine.Object.Instantiate(original);var vertices=mesh.vertices.Select(v=>v*(2.55f/original.bounds.extents.x)).ToArray();mesh.vertices=vertices;mesh.RecalculateBounds();int removed=0;for(int s=0;s<mesh.subMeshCount;s++){var src=original.GetTriangles(s);var dst=new System.Collections.Generic.List<int>();for(int i=0;i<src.Length;i+=3){var p=new[]{src[i],src[i+1],src[i+2]}.Select(k=>row.transform.TransformPoint(vertices[k])).ToArray();if(s==9&&p.All(v=>v.z< -4.49f&&v.y<1.9f&&v.x>.8f)&&p.Any(v=>v.z< -4.6f)){removed++;continue;}dst.AddRange(new[]{src[i],src[i+1],src[i+2]});dst.AddRange(new[]{src[i+2],src[i+1],src[i]});}mesh.SetTriangles(dst,s);}var target=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Scene05HomecomingAnimation/Rowhouse_OperableDoor.asset");EditorUtility.CopySerialized(mesh,target);UnityEngine.Object.DestroyImmediate(mesh);row.sharedMesh=target;var wallCollider=row.GetComponent<MeshCollider>();if(!wallCollider)wallCollider=row.gameObject.AddComponent<MeshCollider>();wallCollider.sharedMesh=target;EditorUtility.SetDirty(target);PrefabUtility.RecordPrefabInstancePropertyModifications(row);
story.Sample(12);float gap=Vector3.Distance(story.Bone("RightMiddle3").position,story.touchPoint);if(gap>.02f)throw new Exception("Touch gap="+gap);story.Sample(0);story.director.time=0;story.director.Evaluate();EditorUtility.SetDirty(story);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(story.gameObject.scene);EditorSceneManager.SaveScene(story.gameObject.scene);File.WriteAllText("Temp/scene05-altar-fix.done","Original geometry restored, removed door triangles="+removed+"; touch gap="+gap);}catch(Exception e){File.WriteAllText("Temp/scene05-altar-fix.error",e.ToString());Debug.LogException(e);}}}



